import { useEffect, useRef } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

export default function LoginSuccess() {
  const navigate = useNavigate();
  const hasVerified = useRef(false); // Prevent double verification

  useEffect(() => {
    // Prevent multiple verifications
    if (hasVerified.current) return;
    
    const verifyToken = async () => {
      const token = new URLSearchParams(window.location.search).get("token");

      if (!token) {
        navigate("/?error=invalid_link");
        return;
      }

      try {
        hasVerified.current = true;
        const res = await axios.get(`http://localhost:3597/api/user/verify?token=${token}`);
        
        // Store token and redirect immediately
        localStorage.setItem("authToken", res.data.token);
        
        // Small delay to ensure localStorage is set
        setTimeout(() => {
          navigate("/dashboard", { replace: true });
        }, 100);
        
      } catch (error) {
        console.error("Verification error:", error);
        // Redirect to login with error
        setTimeout(() => {
          navigate("/?error=expired_link", { replace: true });
        }, 100);
      }
    };

    verifyToken();
  }, [navigate]);

  return (
    <div className="min-h-screen flex items-center justify-center" style={{ background: 'linear-gradient(135deg, #0a0f1e 0%, #1a1f35 100%)' }}>
      <div className="text-center">
        <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-indigo-500/20 flex items-center justify-center animate-pulse-glow">
          <div className="w-10 h-10 border-4 border-indigo-400 border-t-transparent rounded-full animate-spin"></div>
        </div>
        <h2 className="text-2xl font-semibold text-white mb-2">Verifying your magic link...</h2>
        <p className="text-gray-400">Please wait while we securely log you in</p>
      </div>
    </div>
  );
}
